+namespace turbomed::test::integration
+{
+
+class DBListRecoveryIntegrationTest : public DatabaseRecoveryTestFixture
+{
+protected:
+    struct ExpectedPerson
+    {
+        TMString identity;
+        TMString note;
+    };
+
+    void expectPeopleMatch(
+        const DBList<Person>& people,
+        const std::vector<ExpectedPerson>& expected)
+    {
+        ASSERT_EQ(expected.size(), people.entries());
+        for (const auto& expectedPerson : expected)
+        {
+            size_t matches = 0;
+            for (size_t index = 0; index < people.entries(); ++index)
+            {
+                if (people[index].asString(true) == expectedPerson.identity)
+                {
+                    ++matches;
+                    EXPECT_EQ(expectedPerson.note, people[index]->getNotiz());
+                }
+            }
+            EXPECT_EQ(1u, matches);
+        }
+    }
+
+    void expectIterationYieldsExactly(
+        const DBList<Person>& people,
+        const std::vector<TMString>& expected)
+    {
+        ASSERT_EQ(expected.size(), people.entries());
+        std::vector<TMString> actual;
+        for (DBIterator<Person> iterator = people.first();
+             !iterator.done(); iterator.next())
+        {
+            actual.push_back(iterator.get().asString(true));
+        }
+        ASSERT_EQ(expected.size(), actual.size());
+        for (const TMString& expectedIdentity : expected)
+        {
+            size_t matches = 0;
+            for (const TMString& actualIdentity : actual)
+                if (actualIdentity == expectedIdentity)
+                    ++matches;
+            EXPECT_EQ(1u, matches);
+        }
+    }
+};
+
+TEST_F(DBListRecoveryIntegrationTest, HeldEmptyDBListReacquiresAndSeesFirstPostRecoveryInsert)
+{
+    DBList<Person> people(database_->getTable(CLASS_INFO(Person)));
+    ASSERT_TRUE(people.isEmpty());
+    ASSERT_EQ(0u, people.entries());
+
+    recoverDatabase();
+
+    EXPECT_TRUE(people.isEmpty());
+    DBRef<Person> inserted = persistPerson("first after recovery");
+
+    ASSERT_EQ(1u, people.entries());
+    EXPECT_EQ(inserted.asString(true), people[0].asString(true));
+    EXPECT_EQ(TMString("first after recovery"), people[0]->getNotiz());
+}
+
+TEST_F(DBListRecoveryIntegrationTest, HeldDBListReacquiresAndSeesPostRecoveryWrites)
+{
