+#include "StdAfx.h"
+
+#include "ptbase.hxx"
+#include "TMWinDB/DatabaseSessionReconnect.h"
+#include "TMWinDB/TMObjectDB.h"
+
+#include <gtest/gtest.h>
+
+#include <stdexcept>
+#include <string>
+#include <utility>
+#include <vector>
+
+namespace
+{
+
+class StubBaseFailure final : public std::runtime_error
+{
+public:
+    using std::runtime_error::runtime_error;
+};
+
+class StubDatabaseFailure final : public std::runtime_error
+{
+public:
+    using std::runtime_error::runtime_error;
+};
+
+struct StubBase
+{
+    std::string name;
+    std::vector<std::string>* calls = nullptr;
+    bool connected = true;
+    bool opened = true;
+    bool failDisconnect = false;
+    bool failConnect = false;
+    bool failOpen = false;
+    bool failProbe = false;
+    bool preserveStateAfterDisconnect = false;
+    int disconnectCalls = 0;
+    int connectCalls = 0;
+    int openCalls = 0;
+    int probeCalls = 0;
+
+    void record(const char* operation)
+    {
+        if (calls != nullptr)
+            calls->push_back(name + "." + operation);
+    }
+    bool isConnected() const { return connected; }
+    bool isOpen() const { return opened; }
+    void disconnect()
+    {
+        record("disconnect");
+        ++disconnectCalls;
+        if (failDisconnect)
+            throw StubBaseFailure("disconnect failed");
+        if (!preserveStateAfterDisconnect)
+        {
+            connected = false;
+            opened = false;
+        }
+    }
+    void connect()
+    {
+        record("connect");
+        ++connectCalls;
+        if (failConnect)
+            throw StubBaseFailure("connect failed");
+        connected = true;
+    }
+    void open()
+    {
+        record("open");
+        ++openCalls;
+        if (failOpen)
+            throw StubBaseFailure("open failed");
+        if (!connected)
+            throw StubBaseFailure("opened before connect");
+        opened = true;
+    }
+    void probeServerRoundTrip()
+    {
+        record("probe");
+        ++probeCalls;
+        if (failProbe)
+            throw StubBaseFailure("probe failed");
+    }
+};
+
+struct StubDatabase
+{
+    explicit StubDatabase(
+        std::string name = "database",
+        std::vector<std::string>* calls = nullptr)
+        : base{std::move(name), calls}
+    {
+    }
+
+    StubBase base;
+    bool failHeal = false;
+    int healCalls = 0;
+    int resetCalls = 0;
+
+    StubBase& getPtBase() { return base; }
+    void resetPtBaseForRecovery()
+    {
+        base.record("reset");
+        ++resetCalls;
+        base.connected = false;
+        base.opened = false;
+    }
+    void reopenPtBaseAfterRecovery()
+    {
+        base.connect();
+        base.open();
+    }
+    void refreshDatabaseStateAfterReconnect()
+    {
+        base.record("heal");
+        ++healCalls;
+        if (!base.opened)
+            throw StubDatabaseFailure("healed before open");
+        if (failHeal)
+            throw StubDatabaseFailure("cache heal failed");
+    }
+};
+
+TEST(DatabaseSessionReconnect, CacheHealFailureFailsTheWholeRecovery)
+{
+    StubDatabase first;
+    StubDatabase second;
+    second.failHeal = true;
+
+    const bool recovered = turbomed::db::reconnectDatabaseSessions<StubDatabase>(
+        std::vector<StubDatabase*>{&first, &second});
+
+    EXPECT_FALSE(recovered);
+    EXPECT_EQ(1, first.healCalls);
+    EXPECT_EQ(1, second.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, EveryDatabaseHealsBeforeRecoverySucceeds)
+{
+    StubDatabase first;
+    StubDatabase second;
+
+    const bool recovered = turbomed::db::reconnectDatabaseSessions<StubDatabase>(
+        std::vector<StubDatabase*>{&first, &second});
+
+    EXPECT_TRUE(recovered);
+    EXPECT_EQ(1, first.healCalls);
+    EXPECT_EQ(1, second.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, ResetPreservesPtBaseConfiguration)
+{
+    TMObjectDB database;
+    TMPtBase& originalBase = database.getPtBase();
+    originalBase.setServer("configured-server");
+    originalBase.setName("configured-database");
+    originalBase.setSecureCommunication(true);
+#ifdef FO_FULL_DATABASE_ENCRYPTION
+    originalBase.setKey("configured-key");
+    originalBase.setNewKey("configured-new-key");
+#endif
+
+    database.resetPtBaseForRecovery();
+
+    TMPtBase& replacementBase = database.getPtBase();
+    EXPECT_EQ(TMString("configured-server"), replacementBase.getServer());
+    EXPECT_EQ(TMString("configured-database"), replacementBase.getName());
+    EXPECT_TRUE(replacementBase.getSecureCommunication());
+#ifdef FO_FULL_DATABASE_ENCRYPTION
+    EXPECT_EQ(TMString("configured-key"), replacementBase.getKey());
+    EXPECT_EQ(TMString("configured-new-key"), replacementBase.getNewKey());
+#endif
+}
+
+TEST(DatabaseSessionReconnect, UsesGlobalDisconnectOpenAndHealBarriers)
+{
+    std::vector<std::string> calls;
+    StubDatabase first("first", &calls);
+    StubDatabase second("second", &calls);
+
+    ASSERT_TRUE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&first, &second}));
+
+    const std::vector<std::string> expected{
+        "first.disconnect",
+        "second.disconnect",
+        "first.reset",
+        "second.reset",
+        "first.connect",
+        "first.open",
+        "second.connect",
+        "second.open",
+        "first.probe",
+        "second.probe",
+        "first.heal",
+        "second.heal"
+    };
+    EXPECT_EQ(expected, calls);
+    EXPECT_EQ(1, first.base.probeCalls);
+    EXPECT_EQ(1, second.base.probeCalls);
+}
+
+TEST(DatabaseSessionReconnect, DisconnectFailureFailsClosedAfterTryingEveryBase)
+{
+    std::vector<std::string> calls;
+    StubDatabase first("first", &calls);
+    StubDatabase second("second", &calls);
+    first.base.failDisconnect = true;
+
+    EXPECT_FALSE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&first, &second}));
+
+    const std::vector<std::string> expected{
+        "first.disconnect",
+        "second.disconnect"
+    };
+    EXPECT_EQ(expected, calls);
+    EXPECT_EQ(0, first.healCalls);
+    EXPECT_EQ(0, second.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, ConnectFailureNeverPublishesCacheHealing)
+{
+    StubDatabase first;
+    StubDatabase second;
+    first.base.failConnect = true;
+
+    EXPECT_FALSE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&first, &second}));
+    EXPECT_EQ(0, first.healCalls);
+    EXPECT_EQ(0, second.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, OpenFailureNeverPublishesCacheHealing)
+{
+    StubDatabase first;
+    StubDatabase second;
+    first.base.failOpen = true;
+
+    EXPECT_FALSE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&first, &second}));
+    EXPECT_EQ(0, first.healCalls);
+    EXPECT_EQ(0, second.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, AlreadyDisconnectedBaseIsConnectedOpenedAndHealed)
+{
+    StubDatabase database;
+    database.base.connected = false;
+    database.base.opened = false;
+
+    ASSERT_TRUE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&database}));
+    EXPECT_EQ(0, database.base.disconnectCalls);
+    EXPECT_EQ(1, database.base.connectCalls);
+    EXPECT_EQ(1, database.base.openCalls);
+    EXPECT_EQ(1, database.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, StaleOpenStateAfterDisconnectIsResetBeforeReconnect)
+{
+    std::vector<std::string> calls;
+    StubDatabase database("database", &calls);
+    database.base.preserveStateAfterDisconnect = true;
+
+    ASSERT_TRUE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&database}));
+
+    const std::vector<std::string> expected{
+        "database.disconnect",
+        "database.reset",
+        "database.connect",
+        "database.open",
+        "database.probe",
+        "database.heal"
+    };
+    EXPECT_EQ(expected, calls);
+    EXPECT_EQ(1, database.resetCalls);
+}
+
+// A successful connect and open do not prove that the server is responsive.
+// A failed round-trip probe keeps the whole recovery attempt unsuccessful.
+TEST(DatabaseSessionReconnect, ServerRoundTripFailureFailsTheWholeRecovery)
+{
+    StubDatabase first;
+    StubDatabase second;
+    second.base.failProbe = true;
+
+    EXPECT_FALSE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&first, &second}));
+
+    EXPECT_EQ(1, first.base.probeCalls);
+    EXPECT_EQ(1, second.base.probeCalls);
+    EXPECT_EQ(0, first.healCalls);
+    EXPECT_EQ(0, second.healCalls);
+}
+
+TEST(DatabaseSessionReconnect, ServerRoundTripFailureShortCircuitsBeforeHealing)
+{
+    std::vector<std::string> calls;
+    StubDatabase first("first", &calls);
+    StubDatabase second("second", &calls);
+    first.base.failProbe = true;
+
+    EXPECT_FALSE(turbomed::db::reconnectDatabaseSessions<StubDatabase>({&first, &second}));
+
+    EXPECT_EQ(0, first.healCalls);
+    EXPECT_EQ(0, second.healCalls);
+    // First probe throws; second is never reached, matching the fail-closed
+    // discipline the other DatabaseSessionReconnect tests exercise for connect/open.
+    EXPECT_EQ(1, first.base.probeCalls);
+    EXPECT_EQ(0, second.base.probeCalls);
+}
+
