+
+// A raw transport drop leaves the wrapper's connection bookkeeping unchanged.
+// The probe must detect that the server no longer acknowledges requests.
+
+namespace turbomed::test::integration {
+
+class ProbeServerRoundTripFixture : public FastObjectsTestFixture {};
+
+// Baseline: the probe must succeed on a healthy base.
+TEST_F(ProbeServerRoundTripFixture, ProbeSucceedsOnHealthyBase)
+{
+    ASSERT_NO_THROW(tmPtBase_->probeServerRoundTrip());
+}
+
+// Red-then-green: the probe must throw a recoverable exception once the
+// LOCAL transport is torn down behind the wrapper's back.
+TEST_F(ProbeServerRoundTripFixture, ProbeThrowsAfterTransportKilled)
+{
+    // Prove the base was actually live first.
+    ASSERT_NO_THROW(tmPtBase_->probeServerRoundTrip());
+
+    killTransportBehindWrapper();
+
+    bool caughtRecoverable = false;
+    try
+    {
+        tmPtBase_->probeServerRoundTrip();
+    }
+    catch (const TMPoet::Exception& e)
+    {
+        caughtRecoverable = turbomed::db::isRecoverableDatabaseError(e.getErrorCode());
+        RecordProperty("thrown_error_code", std::to_string(e.getErrorCode()));
+    }
+    EXPECT_TRUE(caughtRecoverable)
+        << "probeServerRoundTrip did not throw a recoverable DB error "
+        << "after the LOCAL transport was killed";
+}
+
+// Preserves the Run 51/52 invariant: even with the OLD wrapper's session
+// dead, a fresh TMPtBase against the same LOCAL path still opens. The
+// probe's job is to detect the OLD wrapper's dead state so recovery can
+// swap it for the fresh one.
+TEST_F(ProbeServerRoundTripFixture, FreshWrapperStillOpensAfterTransportKilled)
+{
+    killTransportBehindWrapper();
+
+    TMPtBase fresh(TMString(localFastObjectsServer),
+                   TMString(dbPath_.c_str()));
+    ASSERT_NO_THROW(fresh.connect());
+    ASSERT_NO_THROW(fresh.open(PtOPEN_RW, /*useFactory=*/false));
+    if (fresh.isOpen())      fresh.close();
+    if (fresh.isConnected()) fresh.disconnect();
+}
+
+} // namespace turbomed::test::integration

