+#include "StdAfx.h"
+
+#include <gtest/gtest.h>
+
+#include <algorithm>
+#include <cstdio>
+#include <filesystem>
+#include <fstream>
+#include <set>
+#include <sstream>
+#include <string>
+#include <string_view>
+
+namespace
+{
+
+std::filesystem::path findCppRoot()
+{
+    std::filesystem::path candidate = std::filesystem::path(__FILE__).parent_path();
+    while (!candidate.empty())
+    {
+        if (std::filesystem::is_directory(candidate / "TMWinDB") &&
+            std::filesystem::is_directory(candidate / "TMTestSuite"))
+        {
+            return candidate;
+        }
+
+        const std::filesystem::path parent = candidate.parent_path();
+        if (parent == candidate)
+            break;
+        candidate = parent;
+    }
+    return {};
+}
+
+bool isSourceFile(const std::filesystem::path& path)
+{
+    static const std::set<std::string, std::less<>> extensions{
+        ".cxx", ".cpp", ".h", ".hpp", ".hxx"
+    };
+    return extensions.count(path.extension().string()) != 0;
+}
+
+bool ownsFastObjectsBoundary(const std::filesystem::path& relativePath)
+{
+    if (relativePath.empty())
+        return false;
+
+    static const std::set<std::string, std::less<>> owners{
+        "packages",
+        "TMAdmin",
+        "TMDict",
+        "TMPtSecurity",
+        "TMTestSuite",
+        "TMWinDB"
+    };
+    return owners.count(relativePath.begin()->string()) != 0;
+}
+
+bool ownsRecoveryOperationBoundary(const std::filesystem::path& relativePath)
+{
+    if (relativePath.empty())
+        return false;
+
+    const std::string owner = relativePath.begin()->string();
+    return owner == "TMTestSuite" || owner == "TMWinDB";
+}
+
+bool shouldSkipDirectory(const std::filesystem::path& relativePath)
+{
+    static const std::set<std::string, std::less<>> skippedNames{
+        ".git",
+        ".github",
+        ".vs",
+        "bin",
+        "BuildRules",
+        "Debug",
+        "Debug_ASan",
+        "Design",
+        "MakeAll",
+        "MakeQtProjects",
+        "Modelle",
+        "node_modules",
+        "obj",
+        "output",
+        "packages",
+        "PropertyPages",
+        "Qt",
+        "Release",
+        "x64"
+    };
+
+    return std::any_of(
+        relativePath.begin(), relativePath.end(),
+        [](const auto& component) {
+            return skippedNames.count(component.string()) != 0;
+        });
+}
+
+bool includesFastObjectsHeader(const std::string& line)
+{
+    const std::size_t marker = line.find_first_not_of(" \t");
+    if (marker == std::string::npos || line[marker] != '#')
+        return false;
+
+    const std::size_t directive = line.find_first_not_of(" \t", marker + 1);
+    if (directive == std::string::npos ||
+        line.compare(directive, 7, "include") != 0)
+        return false;
+
+    const std::size_t open = line.find_first_of("<\"", directive + 7);
+    if (open == std::string::npos)
+        return false;
+    const char closeCharacter = line[open] == '<' ? '>' : '\"';
+    const std::size_t close = line.find(closeCharacter, open + 1);
+    if (close == std::string::npos)
+        return false;
+
+    std::string filename = std::filesystem::path(
+        line.substr(open + 1, close - open - 1)).filename().string();
+    for (char& character : filename)
+        character = static_cast<char>(std::tolower(
+            static_cast<unsigned char>(character)));
+
+    if (filename.size() < 5 || filename.compare(filename.size() - 4, 4, ".hxx") != 0)
+        return false;
+    return filename.rfind("pt", 0) == 0 || filename.rfind("poet", 0) == 0;
+}
+
+bool controlsRecoveryOperation(std::string_view line)
+{
+    return line.find("handleDisconnectOrBlock") != std::string::npos ||
+           line.find("RecoveryOperationLease") != std::string::npos ||
+           line.find("recoverOperation(") != std::string::npos ||
+           line.find("isRecoverableDatabaseError") != std::string::npos ||
+           line.find("isInRecoveryModal") != std::string::npos ||
+           line.find("hasReconnectOperation") != std::string::npos ||
+           line.find("shouldRestartOnDisconnect") != std::string::npos;
+}
+
+std::vector<std::filesystem::path> repositorySourceFiles(
+    const std::filesystem::path& cppRoot)
+{
+    const std::filesystem::path repoRoot = cppRoot.parent_path();
+    const std::string repo = repoRoot.generic_string();
+    const std::string command =
+        "git -c core.quotepath=false -c safe.directory=\"" + repo +
+        "\" -C \"" + repo +
+        "\" grep -Il -E \"#[[:space:]]*include\" -- C++";
+
+    std::vector<std::filesystem::path> files;
+    FILE* pipe = _popen(command.c_str(), "r");
+    if (pipe == nullptr)
+        return files;
+
+    std::string buffer(4096, '\0');
+    while (fgets(buffer.data(), static_cast<int>(buffer.size()), pipe) != nullptr)
+    {
+        std::string relative(buffer.c_str());
+        while (!relative.empty() &&
+               (relative.back() == '\r' || relative.back() == '\n'))
+        {
+            relative.pop_back();
+        }
+        if (!relative.empty())
+            files.emplace_back(repoRoot / relative);
+    }
+
+    if (_pclose(pipe) != 0)
+        files.clear();
+    return files;
+}
+
+TEST(RecoveryBoundaryArchitecture, RuntimeModulesRespectDatabaseBoundaries)
+{
+    const std::filesystem::path cppRoot = findCppRoot();
+    ASSERT_FALSE(cppRoot.empty());
+
+    const std::vector<std::filesystem::path> sourceFiles =
+        repositorySourceFiles(cppRoot);
+    ASSERT_FALSE(sourceFiles.empty());
+
+    std::ostringstream includeViolations;
+    std::ostringstream recoveryViolations;
+    std::size_t includeViolationCount = 0;
+    std::size_t recoveryViolationCount = 0;
+
+    for (const std::filesystem::path& path : sourceFiles)
+    {
+        const std::filesystem::path relativePath =
+            path.lexically_relative(cppRoot);
+        if (shouldSkipDirectory(relativePath) ||
+            !isSourceFile(path))
+            continue;
+
+        const bool ownsFastObjects = ownsFastObjectsBoundary(relativePath);
+        const bool ownsRecovery = ownsRecoveryOperationBoundary(relativePath);
+
+        std::ifstream source(path);
+        std::string line;
+        std::size_t lineNumber = 0;
+        while (std::getline(source, line))
+        {
+            ++lineNumber;
+            if (!ownsFastObjects && includesFastObjectsHeader(line))
+            {
+                ++includeViolationCount;
+                includeViolations << relativePath.string() << ':' << lineNumber
+                                  << ": " << line << '\n';
+            }
+            if (!ownsRecovery && controlsRecoveryOperation(line))
+            {
+                ++recoveryViolationCount;
+                recoveryViolations << relativePath.string() << ':' << lineNumber
+                                   << ": " << line << '\n';
+            }
+        }
+    }
+
+    EXPECT_EQ(0u, includeViolationCount) << includeViolations.str();
+    EXPECT_EQ(0u, recoveryViolationCount) << recoveryViolations.str();
+}
+
+TEST(RecoveryBoundaryArchitecture, NestedPtStreamsInheritTheOuterRecoveryPolicy)
+{
+    const std::filesystem::path cppRoot = findCppRoot();
+    ASSERT_FALSE(cppRoot.empty());
+
+    std::ifstream sourceFile(cppRoot / "TMWinDB" / "TMPtStream.h");
+    ASSERT_TRUE(sourceFile);
+    const std::string source{
+        std::istreambuf_iterator<char>(sourceFile),
+        std::istreambuf_iterator<char>()};
+
+    const std::size_t operation = source.find("RecoveryOperationLease operation");
+    ASSERT_NE(std::string::npos, operation);
+    const std::size_t declarationEnd = source.find(';', operation);
+    ASSERT_NE(std::string::npos, declarationEnd);
+    const std::size_t inheritedPolicy = source.find(
+        "RecoveryOperationPolicy::Inherit", operation);
+
+    EXPECT_LT(inheritedPolicy, declarationEnd);
+}
+
+} // namespace

