+TEST(RecoveryOperationGate, ConcurrentReplayableFailuresDrainBeforeRecovery)
+{
+    RecoveryOperationGate gate;
+    std::promise<void> firstReadyPromise;
+    std::promise<void> secondReadyPromise;
+    auto firstReady = firstReadyPromise.get_future();
+    auto secondReady = secondReadyPromise.get_future();
+    std::promise<void> startPromise;
+    std::shared_future<void> start = startPromise.get_future().share();
+
+    auto freeze = [&gate, start](std::promise<void>& readyPromise) {
+        auto operation = gate.acquire(RecoveryOperationPolicy::Replayable);
+        readyPromise.set_value();
+        start.wait();
+        operation.freeze();
+    };
+    auto first = std::async(
+        std::launch::async, freeze, std::ref(firstReadyPromise));
+    auto second = std::async(
+        std::launch::async, freeze, std::ref(secondReadyPromise));
+
+    firstReady.wait();
+    secondReady.wait();
+    startPromise.set_value();
+
+    first.get();
+    second.get();
+    EXPECT_EQ(RecoveryGateState::Freezing, gate.snapshot().state);
+    EXPECT_FALSE(gate.requiresRestart());
+    EXPECT_EQ(0u, gate.snapshot().activeReplayable);
+    EXPECT_EQ(0u, gate.snapshot().activeUncertain);
+
+    ASSERT_TRUE(gate.waitForDrainFor(1s));
