+    auto trigger = gate.acquire(RecoveryOperationPolicy::Replayable);
+    trigger.freeze();
+    ASSERT_TRUE(gate.waitForDrainFor(1s));
+    ASSERT_TRUE(gate.beginRecovery());
+    const auto recoveryGeneration = gate.generationForNewHandles();
+
+    gate.failRecovery();
+
+    EXPECT_FALSE(gate.isGenerationCurrent(oldGeneration));
+    EXPECT_FALSE(gate.isGenerationCurrent(recoveryGeneration));
