+    auto shutdownOperation = shutdownGate.acquire();
+    ASSERT_TRUE(shutdownOperation);
+    EXPECT_EQ(0u, shutdownGate.snapshot().activeUncertain);
+    ASSERT_TRUE(shutdownGate.cancelShutdown());
