+TEST(RecoveryOperationGate, ShutdownWaitsForRecoveryPublication)
+{
+    RecoveryOperationGate gate;
+    auto trigger = gate.acquire(RecoveryOperationPolicy::Replayable);
+    trigger.freeze();
+    ASSERT_TRUE(gate.waitForDrainFor(1s));
+    ASSERT_TRUE(gate.beginRecovery());
+
+    std::promise<void> shutdownStartedPromise;
+    auto shutdownStarted = shutdownStartedPromise.get_future();
+    auto shutdown = std::async(std::launch::async, [&gate, &shutdownStartedPromise] {
+        shutdownStartedPromise.set_value();
+        gate.beginShutdown();
+    });
+
+    shutdownStarted.wait();
+    EXPECT_EQ(std::future_status::timeout, shutdown.wait_for(20ms));
+    ASSERT_TRUE(gate.publishRecovery());
+    ASSERT_EQ(std::future_status::ready, shutdown.wait_for(1s));
+    EXPECT_EQ(RecoveryGateState::ShuttingDown, gate.snapshot().state);
+}
