+TEST(RecoveryOperationGate, ShutdownNestedWorkDoesNotRequireRestart)
+{
+    RecoveryOperationGate gate;
+    auto admitted = gate.acquire(RecoveryOperationPolicy::Replayable);
+
+    gate.beginShutdown();
+    auto cleanup = gate.acquire();
+
+    ASSERT_TRUE(cleanup);
+    EXPECT_EQ(0u, gate.snapshot().activeUncertain);
+    EXPECT_FALSE(gate.requiresRestart());
+}
+
+// Reproduces the Run 51 false-success mode: a Replayable operation observes a
+// recoverable failure (electing itself as freeze owner), then the caller
+// releases the lease without invoking recovery. The gate must not silently
+// return to Open — otherwise the next admission wave believes recovery
+// succeeded. It must transition to Failed so the next admission fails and the
+// dispatch path escalates.
+TEST(RecoveryOperationGate, ObservedFailureWithoutRecoveryTransitionsFailed)
+{
+    RecoveryOperationGate gate;
+    auto lease = gate.acquire(RecoveryOperationPolicy::Replayable);
+
+    ASSERT_FALSE(gate.observeFailure());
+    EXPECT_EQ(RecoveryGateState::Freezing, gate.snapshot().state);
+
+    lease.release();
+
+    EXPECT_NE(RecoveryGateState::Open, gate.snapshot().state);
+    EXPECT_EQ(RecoveryGateState::Failed, gate.snapshot().state);
+}
+
+TEST(RecoveryOperationGate, ObservedFailureAfterRecoverySucceededLeavesOpen)
+{
+    RecoveryOperationGate gate;
+    auto lease = gate.acquire(RecoveryOperationPolicy::Replayable);
+    ASSERT_FALSE(gate.observeFailure());
+    lease.freeze();
+    ASSERT_TRUE(gate.waitForDrainFor(1s));
+    ASSERT_TRUE(gate.beginRecovery());
+    ASSERT_TRUE(gate.publishRecovery());
+
+    EXPECT_EQ(RecoveryGateState::Open, gate.snapshot().state);
+}
+
+TEST(RecoveryOperationGate, ObservedFailureRetriedInPlaceRemainsRecoverable)
+{
+    RecoveryOperationGate gate;
+    auto lease = gate.acquire(RecoveryOperationPolicy::Replayable);
+
+    // Two consecutive observes before either lease-release or recovery.
+    // The second observe must not defeat the invariant.
+    ASSERT_FALSE(gate.observeFailure());
+    EXPECT_FALSE(gate.observeFailure());
+
+    lease.release();
+    EXPECT_EQ(RecoveryGateState::Failed, gate.snapshot().state);
+}
+
