+    "TURBOMED_UNCERTAIN_WRITE_DEATH_TEST_MARKER";
+constexpr char persistedNote[] = "before uncertain write";
+constexpr char uncommittedNote[] = "uncommitted uncertain write";
+constexpr char triggerNote[] = "recovery trigger";
+constexpr int nuclearTerminationExitCode = 0xFA02;
+constexpr int unexpectedRecoveryExitCode = 0xFA03;
+constexpr int metadataFailureExitCode = 0xFA04;
+constexpr int missingUncertaintyExitCode = 0xFA05;
+constexpr int unexpectedReturnExitCode = 0xFA06;
