+class ScopedDeathTestMarker  // NOSONAR(cpp:S4963): RAII environment and marker cleanup requires a destructor.
+{
+public:
+    ScopedDeathTestMarker(const ScopedDeathTestMarker&) = delete;
+    ScopedDeathTestMarker& operator=(const ScopedDeathTestMarker&) = delete;
+
+    explicit ScopedDeathTestMarker(std::filesystem::path candidate)
+    {
+        if (const char* inherited = std::getenv(markerEnvironment);
+            inherited != nullptr && *inherited != '\0')
+        {
+            path = inherited;
+            return;
+        }
+
+        owner = true;
+        path = std::move(candidate);
+        std::error_code error;
+        std::filesystem::remove(path, error);
+        _putenv_s(markerEnvironment, path.string().c_str());
+    }
+
+    ~ScopedDeathTestMarker()
+    {
+        if (!owner)
+            return;
+
+        _putenv_s(markerEnvironment, "");
+        std::error_code error;
+        std::filesystem::remove(path, error);
+    }
+
+    const std::filesystem::path& getPath() const noexcept
+    {
+        return path;
+    }
+
+private:
+    std::filesystem::path path;
+    bool owner = false;
+};
