+class UncertainWriteDeathTest : public DatabaseRecoveryTestFixture  // NOSONAR(cpp:S3656): gtest fixtures require protected members.
+{
+protected:
+    void SetUp() override
+    {
+        ::testing::FLAGS_gtest_death_test_style = "threadsafe";
+        DatabaseRecoveryTestFixture::SetUp();
+    }
+
+    void TearDown() override
+    {
+        DatabaseRecoveryTestFixture::TearDown();
+        if (childTempDirectory.empty())
+            return;
+
+        std::error_code cleanupError;
+        std::filesystem::remove_all(childTempDirectory, cleanupError);
+        EXPECT_FALSE(cleanupError);
+    }
+
+    void createScenarioRecords(DBRef<Person>& target, DBRef<Person>& trigger)
+    {
+        target = persistPerson(persistedNote);
+
+        DBRef<Person> insertedTrigger = persistPerson(triggerNote);
+        const TMString triggerIdentity = insertedTrigger.asString(true);
+        insertedTrigger.clear();
+        trigger = StorableRef<Person>::fromString(triggerIdentity);
+    }
+
+    [[noreturn]] void executeDisconnectedUncertainWrite(
+        const std::filesystem::path& metadataPath,
+        DBRef<Person>& target,
+        DBRef<Person>& trigger)
+    {
+        std::ofstream metadata(metadataPath, std::ios::trunc);
+        if (!metadata.is_open())
+            std::exit(metadataFailureExitCode);
+        metadata << dbPath_ << '\n';
+        metadata.flush();
+        if (!metadata.good())
+            std::exit(metadataFailureExitCode);
+
+        TMPtBaseTransaction transaction(database_->getPtBase());
+        transaction.begin();
+        DBWriteRef<Person> write(target);
+        write->setNotiz(uncommittedNote);
+        write.checkIn();
+
+        if (recoverySnapshot().activeUncertain != 1u)
+            std::exit(missingUncertaintyExitCode);
+
+        database_->getPtBase().disconnect();
+        static_cast<void>(trigger->getNotiz());
+        std::exit(unexpectedReturnExitCode);
+    }
+
+    void resetAndOpenChildDatabase(
+        const std::filesystem::path& metadataPath,
+        DBRef<Person>& target,
+        DBRef<Person>& trigger)
+    {
+        std::ifstream metadata(metadataPath);
+        std::string childDatabasePath;
+        ASSERT_TRUE(std::getline(metadata, childDatabasePath));
+        childTempDirectory =
+            std::filesystem::path(childDatabasePath).parent_path();
+
+        recoveryHandler().disableRuntimeRecovery();
+        target.clear();
+        trigger.clear();
+        database_->close();
+        database_.reset();
+        workspace_.reset();
+
+        workspace_ = std::make_unique<DBWorkspace>();
+        workspace_->initialize(
+            PtTransactionByBase, "TMTestSuiteDeathTestRecovery");
+        database_ = std::make_unique<TMObjectDB>();
+        ASSERT_NO_THROW(database_->open(
+            "LOCAL", childDatabasePath.c_str(), "", DBAccess::write));
+    }
+
+    void expectUncommittedWriteWasRolledBack()
+    {
+        DBList<Person> people(database_->getTable(CLASS_INFO(Person)));
+        ASSERT_EQ(2u, people.entries());
+
+        size_t persistedValues = 0;
+        size_t uncommittedValues = 0;
+        for (size_t index = 0; index < people.entries(); ++index)
+        {
+            const TMString note = people[index]->getNotiz();
+            persistedValues += note == persistedNote ? 1u : 0u;
+            uncommittedValues += note == uncommittedNote ? 1u : 0u;
+        }
+        EXPECT_EQ(1u, persistedValues);
+        EXPECT_EQ(0u, uncommittedValues);
+    }
+
+    std::filesystem::path childTempDirectory;
+};
+
+TEST_F(UncertainWriteDeathTest, DisconnectDuringActiveTransactionTerminatesAndRollsBack)
+{
+    ScopedDeathTestMarker marker(
+        tempDir_ / ("uncertain_write_" + uuid() + ".txt"));
+
+    DBRef<Person> target;
+    DBRef<Person> trigger;
+    createScenarioRecords(target, trigger);
