+
+void DatabaseRecoveryTestFixture::SetUp()
+{
+    TMObjectDBTestFixture::SetUp();
+    if (HasFatalFailure())
+        return;
+
+    configureRuntimeRecovery([this] { ++mRecoveryBeginCalls; });
+}
+
+void DatabaseRecoveryTestFixture::TearDown()
+{
+    expectRecoveryGateQuiescent();
+    TMObjectDBTestFixture::TearDown();
+}
+
+void DatabaseRecoveryTestFixture::configureRuntimeRecovery(
+    std::function<void()> begin)
+{
+    recoveryHandler().configureRuntimeRecovery({
+        [this] {
+            return turbomed::db::reconnectDatabaseSessions<TMObjectDB>({database_.get()});
+        },
+        std::move(begin),
+        [this](bool succeeded) {
+            ++mRecoveryEndCalls;
+            if (!succeeded)
+                mAllRecoveriesSucceeded.store(false);
+        },
+        {},
+        {},
+    });
+}
+
+DatabaseDisconnectRecoveryCoordinator& DatabaseRecoveryTestFixture::recoveryHandler() const
+{
+    return TMPoet::getDatabaseDisconnectRecoveryCoordinator();
+}
+
+turbomed::db::RecoverySnapshot
+DatabaseRecoveryTestFixture::recoverySnapshot() const
+{
+    return recoveryHandler().recoverySnapshot();
+}
+
+void DatabaseRecoveryTestFixture::expectRecoveryGateQuiescent() const
+{
+    const auto snapshot = recoverySnapshot();
+    EXPECT_EQ(turbomed::db::RecoveryGateState::Open, snapshot.state);
+    EXPECT_EQ(0u, snapshot.activeReplayable);
+    EXPECT_EQ(0u, snapshot.activeUncertain);
+    EXPECT_FALSE(snapshot.requiresRestart);
+}
+
+void DatabaseRecoveryTestFixture::expectSuccessfulRecoveries(
+    const turbomed::db::RecoverySnapshot& beforeRecovery,
+    unsigned int expectedCount) const
+{
+    EXPECT_EQ(expectedCount, mRecoveryBeginCalls.load());
+    EXPECT_EQ(expectedCount, mRecoveryEndCalls.load());
+    EXPECT_TRUE(mAllRecoveriesSucceeded.load());
+
+    const auto afterRecovery = recoverySnapshot();
+    EXPECT_EQ(beforeRecovery.generation + expectedCount, afterRecovery.generation);
+    EXPECT_EQ(turbomed::db::RecoveryGateState::Open, afterRecovery.state);
+    EXPECT_EQ(0u, afterRecovery.activeReplayable);
+    EXPECT_EQ(0u, afterRecovery.activeUncertain);
+    EXPECT_FALSE(afterRecovery.requiresRestart);
+}
+
+void DatabaseRecoveryTestFixture::recoverDatabase()
+{
+    const auto beforeRecovery = recoverySnapshot();
+    if (beforeRecovery.state != turbomed::db::RecoveryGateState::Open ||
+        beforeRecovery.activeReplayable != 0 ||
+        beforeRecovery.activeUncertain != 0 ||
+        beforeRecovery.requiresRestart)
+    {
+        throw DatabaseRecoveryTestFailure("Recovery requires a quiescent open gate");
+    }
+
+    if (auto operation = recoveryHandler().beginOperation(
+            turbomed::db::RecoveryOperationPolicy::Replayable);
+        !operation || !recoveryHandler().handleDisconnectOrBlock(operation))
+        throw DatabaseRecoveryTestFailure("Database recovery failed");
+
+    const auto afterRecovery = recoverySnapshot();
+    if (afterRecovery.generation != beforeRecovery.generation + 1 ||
+        afterRecovery.state != turbomed::db::RecoveryGateState::Open ||
+        afterRecovery.activeReplayable != 0 ||
+        afterRecovery.activeUncertain != 0 ||
+        afterRecovery.requiresRestart)
+    {
+        throw DatabaseRecoveryTestFailure("Database recovery left an invalid gate state");
+    }
+}
+
+void DatabaseRecoveryTestFixture::dropRawTransport()
+{
+    TMPtBase& ptBase = database_->getPtBase();
+    ASSERT_TRUE(ptBase.isConnected());
+    ASSERT_TRUE(ptBase.isOpen());
+    ASSERT_NE(nullptr, ptBase.getImp().getPtr());
+    ptBase.getImp()->DisConnect();
+}
+
+DBRef<Person> DatabaseRecoveryTestFixture::persistPerson(const TMString& note)
+{
+    auto ownedObject = std::make_unique<Person>();
+    auto* object = ownedObject.get();
+    object->setNotiz(note);
+    DBRef<Person> person(object);
+    ownedObject.release();
+    if (!database_->insertRef(person))
+        throw DatabaseRecoveryTestFailure("Could not persist Person test record");
+    return person;
+}
+
+void DatabaseRecoveryTestFixture::expectListContainsExactly(
+    const DBList<Person>& people,
+    const std::vector<TMString>& expectedIdentities) const
+{
+    ASSERT_EQ(expectedIdentities.size(), people.entries());
+    for (const TMString& expectedIdentity : expectedIdentities)
+    {
+        size_t matches = 0;
+        for (size_t index = 0; index < people.entries(); ++index)
+        {
+            if (people[index].asString(true) == expectedIdentity)
+                ++matches;
+        }
+        EXPECT_EQ(1u, matches);
+    }
+}
+
