+
+#include <chrono>
+#include <sstream>
+#include <thread>
+
+namespace
+{
+constexpr auto recoveryDrainTimeout = std::chrono::seconds(30);
+}
+
+// Forward-declared to avoid pulling ptbsroot.hxx into this TU.
+o_4b InitPOETThread();
+o_4b DeinitPOETThread();
+
+DatabaseDisconnectRecoveryCoordinator::DatabaseDisconnectRecoveryCoordinator() = default;
+
+// Out-of-line: mReconnectProgressWindow is unique_ptr to a forward-declared type.
+DatabaseDisconnectRecoveryCoordinator::~DatabaseDisconnectRecoveryCoordinator()
+{
+    if (this->mRecoveryThread && this->mRecoveryThread->joinable())
+        this->mRecoveryThread->join();
+}
+
+void DatabaseDisconnectRecoveryCoordinator::configureRuntimeRecovery(RuntimeRecoveryHooks hooks)
+{
+    this->mHooks = std::move(hooks);
+    this->mRuntimeRecoveryEnabled.store(true, std::memory_order_release);
+}
+
+void DatabaseDisconnectRecoveryCoordinator::disableRuntimeRecovery()
+{
+    this->mRuntimeRecoveryEnabled.store(false, std::memory_order_release);
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::tryClaimRecoveryExecution() noexcept
+{
+    RecoveryExecutionState expected = this->mRecoveryExecutionState.load(std::memory_order_acquire);
+    do
+    {
+        if (expected == RecoveryExecutionState::Pending
+            || expected == RecoveryExecutionState::InProgress)
+            return false;
+    } while (!this->mRecoveryExecutionState.compare_exchange_weak(
+        expected, RecoveryExecutionState::Pending));
+    return true;
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::hasReconnectOperation() const noexcept
+{
+    return this->mRuntimeRecoveryEnabled.load(std::memory_order_acquire) &&
+           static_cast<bool>(this->mHooks.operation);
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::isInRecoveryModal() const noexcept
+{
+    const RecoveryExecutionState s = this->mRecoveryExecutionState.load(std::memory_order_acquire);
+    return s == RecoveryExecutionState::Pending || s == RecoveryExecutionState::InProgress;
+}
+
+turbomed::db::RecoveryOperationLease DatabaseDisconnectRecoveryCoordinator::beginOperation(
+    turbomed::db::RecoveryOperationPolicy policy)
+{
+    return this->mOperationGate.acquire(policy);
+}
+
+void DatabaseDisconnectRecoveryCoordinator::observeRecoverableFailure()
+{
+    if (this->isExitInstance())
+    {
+        this->mShutdown.store(
+            ShutdownPhase::ExitingDisconnected,
+            std::memory_order_release);
+        return;
+    }
+
+    if (this->mOperationGate.observeFailure() &&
+        !this->mOperationGate.isRecoveryThread())
+        this->restartOrExit("uncertain_operation");
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::shouldRestartOnDisconnect() const
+{
+    return !this->mOperationGate.isRecoveryThread() &&
+           this->mOperationGate.requiresRestart();
+}
+
+std::uint64_t DatabaseDisconnectRecoveryCoordinator::generationForNewHandles() const
+{
+    return this->mOperationGate.generationForNewHandles();
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::isGenerationCurrent(std::uint64_t generation) const
+{
+    return this->mOperationGate.isGenerationCurrent(generation);
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::canReleaseNativeHandle(std::uint64_t generation) const
+{
+    return this->mOperationGate.canReleaseNativeHandle(generation);
+}
+
+turbomed::db::RecoverySnapshot DatabaseDisconnectRecoveryCoordinator::recoverySnapshot() const
+{
+    return this->mOperationGate.snapshot();
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::handleDisconnectOrBlock(
+    turbomed::db::RecoveryOperationLease& operation)
+{
+    if (!this->hasReconnectOperation())
+    {
+        return false;
+    }
+
+    // Shutdown: don't spawn a recovery the teardown path would deadlock on.
+    if (this->mShutdown.load(std::memory_order_acquire) != ShutdownPhase::Running)
+    {
+        this->mShutdown.store(ShutdownPhase::ExitingDisconnected, std::memory_order_release);
+        return false;
+    }
+
+
+    if (this->mOperationGate.isRecoveryThread())
+    {
+        turbomed::misc::Sentry::addBreadcrumb(
+            "info",
+            "handleDisconnectOrBlock: nested disconnect during recovery, propagating");
+        return false;
+    }
+
+    operation.freeze();
+
+    if (this->mOperationGate.requiresRestart())
+        this->restartOrExit("uncertain_operation");
+
+    // Only the first caller per outage spawns the thread. The rest wait.
+    if (this->tryClaimRecoveryExecution())
+    {
+        if (!this->mOperationGate.waitForDrainFor(recoveryDrainTimeout))
+        {
+            const auto snapshot = this->mOperationGate.snapshot();
+            this->restartOrExit(snapshot.requiresRestart
+                ? "uncertain_operation"
+                : "drain_timeout");
+        }
+
+        this->mRecoveryExecutionState.store(RecoveryExecutionState::InProgress, std::memory_order_release);
+
+        if (this->mRecoveryThread && this->mRecoveryThread->joinable())
+            this->mRecoveryThread->join();
+
+        this->mRecoveryThread = std::make_unique<std::thread>([this] {
+            if (!this->mOperationGate.beginRecovery())
+                this->restartOrExit("begin_recovery_rejected");
+            if (InitPOETThread() != 0)
+            {
+                turbomed::misc::Sentry::addBreadcrumb(
+                    "error", "InitPOETThread failed, aborting recovery");
+                this->mOperationGate.failRecovery();
+                this->reportForcedTermination(
+                    "recovery_thread_initialization_failed",
+                    false);
+                this->terminateAfterUnrecoverableDisconnect();
+            }
+            this->runRecoveryOnThread();
+        });
+    }
+
+    const CWinApp* const app = AfxGetApp();
+    const bool isMainThread = (app != nullptr &&
+                               app->m_nThreadID == ::GetCurrentThreadId());
+    turbomed::misc::Sentry::addBreadcrumb(
+        "info",
+        isMainThread
+            ? "handleDisconnectOrBlock: main thread blocking on condvar"
+            : "handleDisconnectOrBlock: worker thread blocking on condvar");
+
+    std::unique_lock<std::mutex> lock(this->mRecoveryMutex);
+    this->mRecoveryCv.wait(lock, [this] {
+        const RecoveryExecutionState s = this->mRecoveryExecutionState.load(std::memory_order_acquire);
+        return s != RecoveryExecutionState::Pending && s != RecoveryExecutionState::InProgress;
+    });
+    return this->mRecoveryExecutionState.load(std::memory_order_acquire)
+        == RecoveryExecutionState::Succeeded;
+}
+
+void DatabaseDisconnectRecoveryCoordinator::runRecoveryOnThread()
+{
+    std::string_view failureReason = "recovery_retries_exhausted";
+    try
+    {
+        if (this->runRecoveryLifecycle())
+        {
+            if (!this->mOperationGate.publishRecovery())
+            {
+                DeinitPOETThread();
+                this->restartOrExit("publish_recovery_rejected");
+            }
+            const auto snapshot = this->mOperationGate.snapshot();
+            std::ostringstream message;
+            message << "database recovery succeeded: generation="
+                    << snapshot.generation;
+            turbomed::misc::Sentry::addBreadcrumb("info", message.str());
+            this->mRecoveryExecutionState.store(
+                RecoveryExecutionState::Succeeded,
+                std::memory_order_release);
+            this->mRecoveryCv.notify_all();
+            DeinitPOETThread();
+            return;
+        }
+    }
+    catch (TMPoet::Exception& e)
+    {
+        failureReason = "recovery_cycle_exception";
+        const bool transient = turbomed::db::isRecoverableDatabaseDisconnect(e.getErrorCode());
+        std::ostringstream message;
+        message << "recovery thread: "
+                << (transient ? "transient disconnect" : "non-transient exception")
+                << ", error_code=" << e.getErrorCode();
+        turbomed::misc::Sentry::addBreadcrumb(
+            transient ? "info" : "error",
+            message.str());
+    }
+    catch (...) // NOSONAR(cpp:S2738): every recovery failure must enter fail-closed handling.
+    {
+        if (this->mReconnectProgressWindow) this->mReconnectProgressWindow->closeReconnectProgress();
+        turbomed::misc::Sentry::addBreadcrumb(
+            "error", "recovery thread: unknown exception");
+        this->handleRecoveryFailure("recovery_cycle_exception");
+    }
+
+    this->handleRecoveryFailure(failureReason);
+}
+
+[[noreturn]] void DatabaseDisconnectRecoveryCoordinator::handleRecoveryFailure(std::string_view reason)
+{
+    this->mOperationGate.failRecovery();
+    DeinitPOETThread();
+    this->restartOrExit(reason);
+}
+
+void DatabaseDisconnectRecoveryCoordinator::suppressRecoveryDuringShutdown()
+{
+    this->mShutdown.store(ShutdownPhase::Exiting, std::memory_order_release);
+    this->mOperationGate.beginShutdown();
+}
+
+void DatabaseDisconnectRecoveryCoordinator::resumeRecoveryAfterCancelledShutdown()
+{
+    this->mOperationGate.cancelShutdown();
+    this->mShutdown.store(ShutdownPhase::Running, std::memory_order_release);
+}
+
+bool DatabaseDisconnectRecoveryCoordinator::runRecoveryLifecycle()
+{
+    if (this->mReconnectProgressWindow == nullptr)
+        this->mReconnectProgressWindow = std::make_unique<DatabaseReconnectProgressWindow>();
+    DatabaseReconnectProgressWindow* dlg = this->mReconnectProgressWindow.get();
+
+    // Swallow recoverable throws from begin/end so they can't fail the cycle.
+    auto begin = this->mHooks.begin
+        ? std::function<void()>([this]{
+              try { this->mHooks.begin(); }
+              catch (TMPoet::Exception& e) {
+                  if (!turbomed::db::isRecoverableDatabaseError(e.getErrorCode()))
+                      throw;
+                  turbomed::misc::Sentry::addBreadcrumb(
+                      "info",
+                      "recoveryBegin: recoverable DB error during close, swallowed");
+              }
+          })
+        : std::function<void()>{};
+
+    return turbomed::db::runRecoveryLifecycle({
+        this->mHooks.operation,
+        begin,
+        [this, dlg](bool succeeded) {
+            dlg->closeReconnectProgress();
+            if (!this->mHooks.end) return;
+            try { this->mHooks.end(succeeded); }
+            catch (TMPoet::Exception& e) {
+                if (!turbomed::db::isRecoverableDatabaseError(e.getErrorCode()))
+                    throw;
+                turbomed::misc::Sentry::addBreadcrumb(
+                    "info",
+                    "recoveryEnd: recoverable DB error during teardown, swallowed");
+            }
+        },
+        [this, dlg]{
+            dlg->closeReconnectProgress();
+            if (!this->mHooks.userRetry)
+            {
+                turbomed::misc::Sentry::addBreadcrumb(
+                    "info", "database recovery: no further-retry hook configured");
+                return false;
+            }
+            const bool retry = this->mHooks.userRetry();
+            turbomed::misc::Sentry::addBreadcrumb(
+                "info",
+                retry
+                    ? "database recovery: user requested another retry budget"
+                    : "database recovery: user declined further retries");
+            return retry;
+        },
+        [dlg](int attempt, int maximumAttempts) {
+            dlg->showReconnectProgress("CGM TURBOMED");
+            dlg->updateRetryProgress(attempt, maximumAttempts);
+        },
+    });
+}
+
+[[noreturn]] void DatabaseDisconnectRecoveryCoordinator::terminateAfterUnrecoverableDisconnect() const
+{
+    turbomed::misc::Sentry::deinit();
+    const CWinApp* const app = AfxGetApp();
+    if (const bool isMainThread = app != nullptr &&
+            app->m_nThreadID == ::GetCurrentThreadId();
+        !this->isExitInstance() && isMainThread)
+    {
+        AfxMessageBox("Die Verbindung zum Datenbankserver war kurzzeitig unterbrochen.\n"
+            "Bitte prüfen Sie, ob Ihre Netzwerkgeräte (Switches, Router, Server) sowie dieser PC nicht im Energiesparmodus betrieben werden.\n"
+            "Eine WLAN-Verbindung zum Datenbankserver kann weniger stabil sein; wir empfehlen eine kabelgebundene Verbindung.\n\n"
+            "Wenn diese Meldung häufiger erscheint, wenden Sie sich bitte an Ihren Vertriebs- und Servicepartner.\n\n"
+            "CGM TURBOMED wird jetzt beendet. Vielen Dank für Ihr Verständnis.");
+    }
+    ::TerminateProcess(::GetCurrentProcess(), 0xFA02u);
+    std::terminate();
+}
+
+void DatabaseDisconnectRecoveryCoordinator::reportForcedTermination(
+    std::string_view reason,
+    bool restartRequested) const noexcept
+{
+    try
+    {
+        bool expected = false;
+        if (!this->mForcedRestartReported.compare_exchange_strong(
+                expected, true, std::memory_order_acq_rel))
+        {
+            return;
+        }
+
+        const auto snapshot = this->mOperationGate.snapshot();
+        const auto stateName = [](turbomed::db::RecoveryGateState state) -> std::string_view {
+            using turbomed::db::RecoveryGateState;
+            switch (state)
+            {
+            case RecoveryGateState::Open:         return "open";
+            case RecoveryGateState::Freezing:     return "freezing";
+            case RecoveryGateState::Recovering:   return "recovering";
+            case RecoveryGateState::Failed:       return "failed";
+            case RecoveryGateState::ShuttingDown: return "shutting_down";
+            }
+            return "unknown";
+        }(snapshot.state);
+        const std::string_view actionName = restartRequested ? "restart" : "exit";
+
+        std::ostringstream description;
+        description << "reason=" << reason
+                    << ", action=" << actionName
+                    << ", gate_state=" << stateName
+                    << ", active_replayable=" << snapshot.activeReplayable
+                    << ", active_uncertain=" << snapshot.activeUncertain
+                    << ", requires_restart=" << (snapshot.requiresRestart ? "true" : "false")
+                    << ", generation=" << snapshot.generation;
+
+        turbomed::misc::VariantMap tags;
+    tags["db_recovery.reason"] = std::string(reason);
+    tags["db_recovery.action"] = std::string(actionName);
+    tags["db_recovery.gate_state"] = std::string(stateName);
+        tags["db_recovery.requires_restart"] = snapshot.requiresRestart;
+        turbomed::misc::Sentry::captureMessage(
+            turbomed::misc::Level::Error,
+            "Database recovery forced process termination",
+            description.str(),
+            tags);
+    }
+    catch (...) // NOSONAR(cpp:S2738): diagnostics must never block mandatory termination.
+    {
+    }
+}
+
+[[noreturn]] void DatabaseDisconnectRecoveryCoordinator::restartOrExit(std::string_view reason) const
+{
+    this->reportForcedTermination(reason, static_cast<bool>(this->mHooks.restart));
+    try
+    {
+        if (this->mHooks.restart)
+            this->mHooks.restart();
+    }
+    catch (...) // NOSONAR(cpp:S2738): restart hook failure must not prevent process termination.
+    {
+    }
+    this->terminateAfterUnrecoverableDisconnect();
+}

