+class TMWINDB_EXT_API DatabaseDisconnectRecoveryCoordinator
+{
+public:
+    struct RuntimeRecoveryHooks
+    {
+        std::function<bool()>     operation;
+        std::function<void()>     begin;
+        std::function<void(bool)> end;
