+
+    turbomed::db::RecoveryOperationLease beginOperation(
+        turbomed::db::RecoveryOperationPolicy policy =
+            turbomed::db::RecoveryOperationPolicy::Uncertain);
+    void observeRecoverableFailure();
+    bool shouldRestartOnDisconnect() const;
+    std::uint64_t generationForNewHandles() const;
+    bool isGenerationCurrent(std::uint64_t generation) const;
+    bool canReleaseNativeHandle(std::uint64_t generation) const;
+    turbomed::db::RecoverySnapshot recoverySnapshot() const;
+
+    // Blocks until recovery finishes. True means the caller should retry.
+    bool handleDisconnectOrBlock(
+        turbomed::db::RecoveryOperationLease& operation);
+
+    bool hasReconnectOperation() const noexcept;
+
+    // True while a cycle is in flight. The pump filter drops DB-touching messages.
+    bool isInRecoveryModal() const noexcept;
+
+    void suppressRecoveryDuringShutdown();
+    // Cancels suppressRecoveryDuringShutdown() when the user aborts the close prompt.
+    void resumeRecoveryAfterCancelledShutdown();
+
+    bool isExitInstance() const noexcept
+    {
+        return this->mShutdown.load(std::memory_order_acquire) != ShutdownPhase::Running;
+    }
+
+    // Latched when a disconnect fires during shutdown, preventing dead-base loops.
+    bool isShutdownDisconnect() const noexcept
+    {
+        return this->mShutdown.load(std::memory_order_acquire) == ShutdownPhase::ExitingDisconnected;
+    }
+
+private:
+    // Single source of truth for cycle liveness and last-cycle outcome.
+    enum class RecoveryExecutionState {
+        Idle,
+        Pending,
+        InProgress,
+        Succeeded,
+    };
+
+    RuntimeRecoveryHooks mHooks;
+
+    std::atomic<bool> mRuntimeRecoveryEnabled{false};
+
+    std::atomic<RecoveryExecutionState>   mRecoveryExecutionState{RecoveryExecutionState::Idle};
+    std::mutex                   mRecoveryMutex;
+    std::condition_variable      mRecoveryCv;
+    std::unique_ptr<std::thread> mRecoveryThread;
+
+    enum class ShutdownPhase { Running, Exiting, ExitingDisconnected };
+    std::atomic<ShutdownPhase> mShutdown{ShutdownPhase::Running};
+
+    std::unique_ptr<DatabaseReconnectProgressWindow> mReconnectProgressWindow;
+    turbomed::db::RecoveryOperationGate mOperationGate;
+    mutable std::atomic<bool> mForcedRestartReported{false};
+
+    [[noreturn]] void terminateAfterUnrecoverableDisconnect() const;
+    [[noreturn]] void restartOrExit(std::string_view reason) const;
+    void reportForcedTermination(std::string_view reason, bool restartRequested) const noexcept;
+    void runRecoveryOnThread();
+    bool runRecoveryLifecycle();
+    [[noreturn]] void handleRecoveryFailure(std::string_view reason);
+    bool tryClaimRecoveryExecution() noexcept;
+};

