+#pragma once
+
+#include "DeclSpec.h"
+#include "DatabaseRecoveryLifecycle.h"
+
+#include <chrono>
+#include <functional>
+
+namespace turbomed::db
+{
+
+TMWINDB_EXT_API bool isRecoverableDatabaseDisconnect(int errorCode) noexcept;
+
+TMWINDB_EXT_API bool isRecoverableDatabaseError(int errorCode) noexcept;
+
+struct ReconnectAttemptPolicy
+{
+    int                       maximumAttempts  = 5;
+    std::chrono::milliseconds initialBackoff = std::chrono::milliseconds(500);
+    std::chrono::milliseconds maximumBackoff     = std::chrono::seconds(4);
+    double                    backoffMultiplier   = 2.0;
+};
+
+// Invoked before each retry (not the first attempt) with 1-based retry index
+// and the retry budget (maximumAttempts - 1). nullptr for non-UI callers.
+using ReconnectProgressCallback = std::function<void(int attempt, int maximumAttempts)>;
+
+// operation returns true on success, false to retry. Exceptions propagate.
+// std::function on the boundary is intentional: TMWINDB_EXT_API is a DLL
+// export, and templating would force every consumer to instantiate the body.
+TMWINDB_EXT_API bool runReconnectAttemptsWithBackoff(
+    const std::function<bool()>& operation,
+    const ReconnectAttemptPolicy&           policy   = {},
+    const ReconnectProgressCallback&            progress = {});
+
+inline bool runRecoveryLifecycle(const RecoveryLifecycleCallbacks& hooks,
+                             const ReconnectAttemptPolicy&   policy = {})
+{
+    return runRecoveryLifecycle(hooks, [&hooks, &policy](const std::function<bool()>& op) {
+        return runReconnectAttemptsWithBackoff(op, policy, hooks.progress);
+    });
+}
+
+} // namespace turbomed::db

